import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"隔舱模式（Bulkhead）","description":"","frontmatter":{},"headers":[],"relativePath":"evolution/bulkhead.md","filePath":"evolution/bulkhead.md","lastUpdated":1791572405000}`),a={name:`evolution/bulkhead.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="隔舱模式-bulkhead" tabindex="-1">隔舱模式（Bulkhead） <a class="header-anchor" href="#隔舱模式-bulkhead" aria-label="Permalink to “隔舱模式（Bulkhead）”">​</a></h1><p>隔舱把调用方的资源——线程、连接、内存、队列——按下游或业务分成几个互不占用的池子：一个下游变慢只吃光自己那一格，别的格子照常工作。它出自 Nygard 的《Release It!》[S12]，词取自船的舱壁：船底分仓，一舱进水船不沉。没有隔舱的服务是通舱设计，所有请求共用一个线程池或连接池，一个慢下游就能把整个池子占满，拖垮与它无关的功能。<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>篇里&quot;变慢的下游把线程、连接、内存一起拖住&quot;，防住这一步的前半段靠的就是隔舱：先分仓，再谈单个仓里的熔断与<a href="/hello-design-patterns/evolution/timeout">超时</a>。</p><h2 id="隔什么、按什么隔" tabindex="-1">隔什么、按什么隔 <a class="header-anchor" href="#隔什么、按什么隔" aria-label="Permalink to “隔什么、按什么隔”">​</a></h2><p>按隔离的载体分三种：</p><ul><li><strong>线程池隔离</strong>：每个下游一个线程池，占用上限明确，代价是线程切换与排队延迟。Java 的传统做法（Hystrix 的线程池组）。</li><li><strong>信号量隔离</strong>：不换线程，只数&quot;同时在飞的请求数&quot;，到了上限直接拒绝。开销小，适合纯内存或低延迟调用。Resilience4j 的 <code>Bulkhead</code> 默认就是信号量。</li><li><strong>连接池隔离</strong>：数据库、HTTP 客户端按用途分池——交易读一个池、报表一个池，慢查询占满报表池不影响交易池。</li></ul><p>格子怎么划：按下游分（A 服务一格、B 服务一格），再按业务优先级分（支付一格、导出一格）。判断标准是<strong>故障与迟缓的量级差异</strong>：导出报表慢不该让支付下单跟着等队列。</p><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p>适用于：一个进程同时访问多个延迟量级不同的下游，或一个进程同时服务多个业务优先级。</p><p>不适用的三种：</p><ol><li>资源本来就不紧张的小服务：多套池子徒增配置与调参成本，隔离收益接近零。</li><li>下游数量多而流量都小：为每个下游建池，池子利用率低，内存先扛不住，应合并为按&quot;下游类别&quot;分格。</li><li>纯进程内调用：本地对象之间没有连接与线程的争夺面。</li></ol><h2 id="与其他模式的关系" tabindex="-1">与其他模式的关系 <a class="header-anchor" href="#与其他模式的关系" aria-label="Permalink to “与其他模式的关系”">​</a></h2><ul><li>与<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>：隔舱限制同时在飞的数量（空间上隔离），熔断按失败率决定要不要发（时间上断闸）。顺序是先隔舱后熔断——隔舱保证一个仓出事不传染，熔断保证出事的仓尽快停止无效请求。</li><li>与<a href="/hello-design-patterns/evolution/timeout">超时</a>：超时把慢调用变短，隔舱把慢调用的占用封顶，两者一起决定最坏情况下一个慢下游吃掉多少资源。</li><li>与<a href="/hello-design-patterns/evolution/retry">重试</a>：重试的流量计入所在舱格的上限，隔舱保证重试风暴最多打满一格。</li><li>与<a href="/hello-design-patterns/concurrency/semaphore">信号量</a>：信号量是隔舱的计数原语，并发篇里它解决的是互斥与限流，隔舱给它加上&quot;按下游分格、拒绝要有降级&quot;的用法。</li><li>与<a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者</a>：队列加固定消费者组是隔舱的异步形态，队列长度就是仓壁。</li><li>与<a href="/hello-design-patterns/concurrency/thread-pool">线程池</a>：线程池隔离的基础设施，隔舱决定&quot;建几个池、每个池多大&quot;。</li></ul><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to “关键参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>取值依据</th><th>设错的后果</th></tr></thead><tbody><tr><td>每格并发上限</td><td>下游能承受的并发（正常 QPS × P99 延迟）</td><td>太小，正常流量排队；太大，隔离名存实亡</td></tr><tr><td>排队上限 / 等待时长</td><td>超过并发上限后的等待位数量</td><td>无限排队等于没有隔舱，请求在队列里慢慢过期</td></tr><tr><td>格子数量</td><td>按下游数加业务优先级，一般 2–5 个</td><td>每下游一格，在下游多时把内存切碎</td></tr></tbody></table><p>每格的容量依据是<strong>下游能承受多少</strong>，不是调用方有多少线程：下游只扛得住 50 并发，给 500 的格子是把下游打死。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Go 实现：每个舱格一个信号量，占不到就拒绝，不排队。</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> bulkhead</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#B392F0;">errors</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">var</span><span style="color:#E1E4E8;"> ErrFull </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> errors.</span><span style="color:#B392F0;">New</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;bulkhead full&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// Cell 是一个舱格：最多 maxInFlight 个调用同时在飞，占不到就拒绝</span></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> Cell</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	sem </span><span style="color:#F97583;">chan</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;">{}</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#B392F0;"> New</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">maxInFlight</span><span style="color:#F97583;"> int</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">*</span><span style="color:#B392F0;">Cell</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">	return</span><span style="color:#F97583;"> &amp;</span><span style="color:#B392F0;">Cell</span><span style="color:#E1E4E8;">{sem: </span><span style="color:#B392F0;">make</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">chan</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;">{}, maxInFlight)}</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// Do 占一格执行 fn；占不到返回 ErrFull，由调用方走降级</span></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#E1E4E8;"> (</span><span style="color:#FFAB70;">c </span><span style="color:#F97583;">*</span><span style="color:#B392F0;">Cell</span><span style="color:#E1E4E8;">) </span><span style="color:#B392F0;">Do</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">fn</span><span style="color:#F97583;"> func</span><span style="color:#E1E4E8;">() </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">	select</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">	case</span><span style="color:#E1E4E8;"> c.sem </span><span style="color:#F97583;">&lt;-</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;">{}{}:</span></span>
<span class="line"><span style="color:#F97583;">		defer</span><span style="color:#F97583;"> func</span><span style="color:#E1E4E8;">() { </span><span style="color:#F97583;">&lt;-</span><span style="color:#E1E4E8;">c.sem }()</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#B392F0;"> fn</span><span style="color:#E1E4E8;">()</span></span>
<span class="line"><span style="color:#F97583;">	default</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#E1E4E8;"> ErrFull</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><p>调用方按下游建格，容量按各自下游能承受的并发设：</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">var</span><span style="color:#E1E4E8;"> (</span></span>
<span class="line"><span style="color:#E1E4E8;">	payCell    </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> bulkhead.</span><span style="color:#B392F0;">New</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">50</span><span style="color:#E1E4E8;">) </span><span style="color:#818e99;">// 支付：贵、量小</span></span>
<span class="line"><span style="color:#E1E4E8;">	reportCell </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> bulkhead.</span><span style="color:#B392F0;">New</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">10</span><span style="color:#E1E4E8;">) </span><span style="color:#818e99;">// 报表导出：慢，占满了也不影响支付</span></span>
<span class="line"><span style="color:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Java 侧不必自己写：Resilience4j 的 <code>Bulkhead</code>（<code>maxConcurrentCalls</code>、<code>maxWaitDuration</code>）与线程池变体 <code>ThreadPoolBulkhead</code>（<code>maxThreadPoolSize</code>、<code>queueCapacity</code>）、Hystrix 的线程池隔离（<code>execution.isolation.strategy=THREAD</code>，已停更）、Sentinel 的槽位链按资源隔离，都是同一思路。</p><h2 id="接入时的三件小事" tabindex="-1">接入时的三件小事 <a class="header-anchor" href="#接入时的三件小事" aria-label="Permalink to “接入时的三件小事”">​</a></h2><ol><li><strong>拒绝要有去向</strong>：<code>ErrFull</code> 出来后走降级（默认值、转异步队列、明确报错），和熔断打开一样要给用户交代。</li><li><strong>上限按下游能力设</strong>：每格容量是下游能承受的量，拍脑袋按调用方线程数设等于没隔。</li><li><strong>监控每格占用率</strong>：占用率长期贴近 1 的格子先扩容或熔断，这是容量规划的第一手数据。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>、<a href="/hello-design-patterns/evolution/timeout">超时</a>、<a href="/hello-design-patterns/evolution/retry">重试</a>：同出 Release It! 的稳定性三模式。</li><li><a href="/hello-design-patterns/concurrency/semaphore">信号量模式</a>：隔舱的计数原语。</li><li><a href="/hello-design-patterns/concurrency/thread-pool">线程池模式</a>：线程池隔离的基础设施。</li><li><a href="/hello-design-patterns/evolution/overview">现代演进导读</a>：本篇为什么放在 GoF 之后。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S12] Michael T. Nygard，《Release It!》第 2 版，Pragmatic Bookshelf，2018。舱壁隔离的原始出处。</li><li>[S13] Chris Richardson，《Microservices Patterns》，2018，服务间资源隔离的实践口径。</li></ul>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};